"""R3h 差異部署（放棄上櫃前10）：正式版 r3f → ★權值股只標上市市值前50、不再抓 TPEx 收盤價。
insti_query_r1.py 換成 R3h；app.py 只把排行榜 RK_R3 段（檔尾）整段換成 R3h 版。其他檔案不動。
用法：python3 -B r3h_delta.py --src DIR --cand DIR
"""
import base64, gzip, hashlib, os, subprocess, sys
APP_OLD = "47e54b77f4f1fa97"
INSTI_OLD = "ae1786b8ebaa819c"
INSTI_NEW = "275f0127264550ca52b8783eaa0f77840d68e5052b358a60b9b6b75ae9eabbbd"
G = lambda s: gzip.decompress(base64.b64decode(s))
INSTI_GZ, OLD_GZ, NEW_GZ = "", "", ""
sha = lambda b: hashlib.sha256(b).hexdigest()
def need(c, m):
    if not c:
        print("[R3H_STOP]", m); sys.exit(1)
a = sys.argv[1:]
src, cand = a[a.index("--src") + 1], a[a.index("--cand") + 1]
app_b, ins_b = open(os.path.join(src, "app.py"), "rb").read(), open(os.path.join(src, "insti_query_r1.py"), "rb").read()
need(sha(app_b).startswith(APP_OLD), "app.py 不是正式版 r3f " + sha(app_b)[:16])
need(sha(ins_b).startswith(INSTI_OLD), "insti 不是正式版 R3f " + sha(ins_b)[:16])
new_ins = G(INSTI_GZ)
need(sha(new_ins) == INSTI_NEW, "內嵌 R3h 檔 SHA 不符")
old_blk, new_blk = G(OLD_GZ).decode("utf-8"), G(NEW_GZ).decode("utf-8")
app_t = app_b.decode("utf-8")
need(app_t.count(old_blk) == 1, "app.py 內找不到唯一的 RK_R3 段")
new_app = app_t.replace(old_blk, new_blk).encode("utf-8")
compile(new_app, "app.py", "exec"); compile(new_ins, "insti_query_r1.py", "exec")
need(not os.path.exists(cand), "候選目錄已存在")
os.makedirs(os.path.dirname(cand), exist_ok=True)
subprocess.run(["cp", "-al", src, cand], check=True)
for name, data in (("app.py", new_app), ("insti_query_r1.py", new_ins)):
    tmp = os.path.join(cand, "." + name + ".tmp")
    open(tmp, "wb").write(data)
    os.replace(tmp, os.path.join(cand, name))
    need(os.stat(os.path.join(cand, name)).st_nlink == 1, name + " 仍是硬連結")
need(sha(open(os.path.join(src, "app.py"), "rb").read()) == sha(app_b), "基底被改動")
print(f"[R3H_PATCHED] candidate={cand} app={sha(new_app)[:16]} insti={sha(new_ins)[:16]}")
